mapper.select:
SELECT c.member_id, c.sku, p.product_name, p.price, c.qty, c.added_at
  FROM CART_ITEMS c
  JOIN PRODUCTS p ON c.sku = p.sku
 WHERE c.member_id = #{memberId}
   AND c.sku = #{sku}

mapper.update:
UPDATE CART_ITEMS
   SET qty = #{qty}
 WHERE member_id = #{memberId}
   AND sku = #{sku}

mapper.delete:
DELETE FROM CART_ITEMS
 WHERE member_id = #{memberId}
   AND sku = #{sku}
